string s = "12,,3x", tok;
stringstream ss(s);
// 이렇게 쓰기 쉽다
while (getline(ss, tok, ',')) cout << stoi(tok) << ' ';
// 이렇게 고친다
stringstream safe(s);
while (getline(safe, tok, ',')) {
    if (tok.empty()) { cout << "빈값 "; continue; }
    size_t pos = 0;
    try {
        int n = stoi(tok, &pos);
        if (pos != tok.size()) throw invalid_argument("suffix");
        cout << n << ' ';
    } catch (const exception&) { cout << "오류 "; }
}
```

